  await p.choose('task-filter', 'Open');
  p.byId('task-due-date-1').value = '2024-02-29';
  await p.byId('task-due-date-1').parent.fire('submit');
  await settle();
  p.byId('due-from').value = '2024-02-29';
  p.byId('due-through').value = '2024-02-29';
